// Synthetic canonical HTTP responses exercise real owner validation and journal.
fn gold_capacity_context()->(Context,State,std::path::PathBuf){
 let dir=std::env::temp_dir().join(format!("nt2-gold-capacity-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&dir).unwrap();
 let binding=Binding{context:[1;16],service_origin:"https://fixture.invalid".into(),service_id:"service".into(),service_epoch:uuid::Uuid::new_v4().to_string(),session_epoch:uuid::Uuid::new_v4().to_string(),principal_id:uuid::Uuid::new_v4().to_string(),scope:wire::Scope{room_id:Some(uuid::Uuid::new_v4().to_string()),run_id:Some(uuid::Uuid::new_v4().to_string()),run_epoch:Some(uuid::Uuid::new_v4().to_string()),config_revision:Some(1),attachment_id:Some(uuid::Uuid::new_v4().to_string()),world_token:Some(uuid::Uuid::new_v4().to_string())}};
 let mut consumer=LocalConsumer::new(crate::g3_journal::Journal::open(&dir.join("originals.jsonl")).unwrap());consumer.bind(binding.clone()).unwrap();let owner=HttpOwner::new(binding.clone(),zeroize::Zeroizing::new("fixture-token".into()),Arc::new(std::sync::atomic::AtomicU64::new(1))).unwrap();
 (Context{binding,consumer,owner,events:None,items:false,item_players:json!([])},State::default(),dir)
}
fn gold_capacity_reply(bytes:&[u8],journal:&SharedJournal,error:Option<&str>)->Vec<u8>{
 let q=protocol_g3::request(bytes).unwrap();let id=q.gold_intent.as_ref().and_then(|v|v.operation_id.as_ref()).or_else(||q.gold_status.as_ref().and_then(|v|v.operation_id.as_ref())).or_else(||q.gold_receipt.as_ref().and_then(|v|v.operation_id.as_ref())).unwrap();let p=journal.pending().find(|p|p.record.original.operation_id==*id).unwrap();let o=p.record.original;let scope:wire::Scope=serde_json::from_str(&o.scope_json).unwrap();
 let op=wire::Operation{operation_id:Some(id.clone()),principal_id:Some(o.principal_id.clone()),run_id:scope.run_id.clone(),attachment_id:scope.attachment_id.clone(),world_token:scope.world_token.clone(),direction:Some(o.direction.clone()),amount:Some(o.amount),payload_digest:Some(crate::g3_journal::operation_digest(&o).unwrap()),delivery_id:Some("44444444-4444-4444-8444-444444444444".into()),state:Some(if o.direction=="deposit"{"awaiting_local"}else{"reserved"}.into()),effect_allowed:Some(true),save_persistence:Some("unproven".into()),..Default::default()};
 serde_json::to_vec(&wire::Response{major:Some(1),revision:Some(protocol_g3::REVISION.into()),service_id:q.service_id,service_epoch:q.service_epoch,request_id:q.request_id,operation:error.is_none().then_some(op),error:error.map(|code|wire::Error{code:Some(code.into()),..Default::default()}),..Default::default()}).unwrap()
}
fn gold_capacity_cleanup(c:Context,dir:std::path::PathBuf){drop(c);std::fs::remove_file(dir.join("originals.jsonl")).unwrap();std::fs::remove_dir(dir).unwrap();}
#[test]fn gold_busy_retains_same_original_and_recovers_status_first_without_any_effect(){tauri::async_runtime::block_on(async{
 let(mut c,mut s,dir)=gold_capacity_context();let id=uuid::Uuid::new_v4().to_string();let seen=Arc::new(Mutex::new(Vec::<(String,String)>::new()));let log=seen.clone();let journal=c.consumer.journal.clone();let intents=Arc::new(std::sync::atomic::AtomicU64::new(0));let count=intents.clone();
 c.owner.test_transport(move|bytes|{let q=protocol_g3::request(bytes).unwrap();let(kind,key,error)=if let Some(v)=&q.gold_intent{("intent",v.operation_id.clone().unwrap(),(count.fetch_add(1,std::sync::atomic::Ordering::AcqRel)==0).then_some("CAPACITY"))}else{("status",q.gold_status.as_ref().unwrap().operation_id.clone().unwrap(),Some("NOT_FOUND"))};log.lock().unwrap().push((kind.into(),key));Ok(gold_capacity_reply(bytes,&journal,error))});
 assert_eq!(action(&mut c,&mut s,Input::Submit{id:id.clone(),direction:"deposit".into(),amount:10}).await.unwrap_err(),"CAPACITY");let p=c.consumer.journal.pending().next().unwrap();let original=serde_json::to_value(&p.record.original).unwrap();assert_eq!(p.record.phase,Phase::Requested);assert_eq!(s.submission.as_ref().unwrap()["status"],"unresolved");
 recover_gold_original(&mut c,&mut s,&p).await.unwrap();let p=c.consumer.journal.pending().next().unwrap();assert_eq!(serde_json::to_value(&p.record.original).unwrap(),original);assert_eq!(p.record.phase,Phase::ServerAccepted);assert_eq!(s.submission.as_ref().unwrap()["status"],"accepted");assert!(s.permissions.is_empty()&&s.effect.is_none());assert_eq!(*seen.lock().unwrap(),vec![("intent".into(),id.clone()),("status".into(),id.clone()),("intent".into(),id)]);assert!(message("CAPACITY").contains("busy"));assert!(message("BANK_FULL").contains("full"));gold_capacity_cleanup(c,dir);
});}
#[test]fn gold_initial_and_retried_bank_full_refuse_only_the_unissued_original(){tauri::async_runtime::block_on(async{
 for first_busy in [false,true]{let(mut c,mut s,dir)=gold_capacity_context();let id=uuid::Uuid::new_v4().to_string();let journal=c.consumer.journal.clone();let intents=Arc::new(std::sync::atomic::AtomicU64::new(0));let count=intents.clone();
  c.owner.test_transport(move|bytes|{let q=protocol_g3::request(bytes).unwrap();let error=if q.gold_intent.is_some(){if count.fetch_add(1,std::sync::atomic::Ordering::AcqRel)==0&&first_busy{"CAPACITY"}else{"BANK_FULL"}}else{"NOT_FOUND"};Ok(gold_capacity_reply(bytes,&journal,Some(error)))});
  assert!(action(&mut c,&mut s,Input::Submit{id:id.clone(),direction:"deposit".into(),amount:10}).await.is_err());if first_busy{let p=c.consumer.journal.pending().next().unwrap();assert_eq!(recover_gold_original(&mut c,&mut s,&p).await.unwrap_err(),"BANK_FULL");}
  assert_eq!(c.consumer.journal.pending().next().unwrap().record.phase,Phase::Refused);assert_eq!(s.submission.as_ref().unwrap()["status"],"refused");let before=intents.load(std::sync::atomic::Ordering::Acquire);action(&mut c,&mut s,Input::Submit{id:id.clone(),direction:"deposit".into(),amount:10}).await.unwrap();assert_eq!(intents.load(std::sync::atomic::Ordering::Acquire),before);assert!(s.permissions.is_empty()&&s.effect.is_none());gold_capacity_cleanup(c,dir);
 }
});}
#[test]fn gold_bank_full_after_acceptance_or_receipt_preserves_evidence_without_replay(){tauri::async_runtime::block_on(async{
 for applied in [false,true]{let(mut c,mut s,dir)=gold_capacity_context();let id=uuid::Uuid::new_v4().to_string();let journal=c.consumer.journal.clone();c.owner.test_transport(move|bytes|{let q=protocol_g3::request(bytes).unwrap();Ok(gold_capacity_reply(bytes,&journal,q.gold_receipt.is_some().then_some("BANK_FULL")))});
  action(&mut c,&mut s,Input::Submit{id:id.clone(),direction:"deposit".into(),amount:10}).await.unwrap();let original=c.consumer.journal.pending().next().unwrap();let delivery=original.record.delivery.clone();assert_eq!(gold_intent_result(&mut c,&mut s,&id,Err("BANK_FULL".into())).unwrap_err(),"BANK_FULL");assert_eq!(c.consumer.journal.pending().next().unwrap().record.phase,Phase::ServerAccepted);assert_eq!(s.submission.as_ref().unwrap()["status"],"unresolved");
  let digest=crate::g3_journal::operation_digest(&original.record.original).unwrap();let attempt="a".repeat(32);action(&mut c,&mut s,Input::Prepare{id:id.clone(),digest:digest.clone(),attempt:attempt.clone()}).await.unwrap();assert_eq!(action(&mut c,&mut s,Input::Result{id:id.clone(),digest,attempt,applied}).await.unwrap_err(),"BANK_FULL");let p=c.consumer.journal.pending().next().unwrap();assert_eq!(p.record.phase,if applied{Phase::AppliedSession}else{Phase::Uncertain});assert_eq!(p.record.delivery,delivery);assert_eq!(p.record.original.operation_id,id);assert!(c.consumer.journal.prepare_effect(&id).is_err());assert!(s.permissions.is_empty()&&s.effect.is_none());gold_capacity_cleanup(c,dir);
 }
});}
#[test]fn gold_busy_recovery_never_reissues_cold_or_substituted_scope(){tauri::async_runtime::block_on(async{
 let(mut c,mut s,dir)=gold_capacity_context();let id=uuid::Uuid::new_v4().to_string();let journal=c.consumer.journal.clone();let intents=Arc::new(std::sync::atomic::AtomicU64::new(0));let count=intents.clone();c.owner.test_transport(move|bytes|{let q=protocol_g3::request(bytes).unwrap();if q.gold_intent.is_some(){count.fetch_add(1,std::sync::atomic::Ordering::AcqRel);}Ok(gold_capacity_reply(bytes,&journal,Some(if q.gold_intent.is_some(){"CAPACITY"}else{"NOT_FOUND"})))});
 assert!(action(&mut c,&mut s,Input::Submit{id:id.clone(),direction:"deposit".into(),amount:10}).await.is_err());let p=c.consumer.journal.pending().next().unwrap();let mut cold=p.clone();cold.restored=true;assert!(recover_gold_original(&mut c,&mut s,&cold).await.is_err());let old=c.binding.scope.world_token.replace(uuid::Uuid::new_v4().to_string());assert!(recover_gold_original(&mut c,&mut s,&p).await.is_err());c.binding.scope.world_token=old;assert_eq!(intents.load(std::sync::atomic::Ordering::Acquire),1);assert_eq!(c.consumer.journal.pending().next().unwrap().record.phase,Phase::Requested);assert!(s.permissions.is_empty());gold_capacity_cleanup(c,dir);
});}

#[test]fn accepted_live_original_waits_for_fresh_prepare_but_cold_or_changed_scope_keeps_recovery(){tauri::async_runtime::block_on(async{
 let(mut c,mut s,dir)=gold_capacity_context();let journal=c.consumer.journal.clone();c.owner.test_transport(move|bytes|Ok(gold_capacity_reply(bytes,&journal,None)));let id=uuid::Uuid::new_v4().to_string();action(&mut c,&mut s,Input::Submit{id:id.clone(),direction:"deposit".into(),amount:5}).await.unwrap();
 let p=c.consumer.journal.pending().next().unwrap();let op=&s.operations[&id];assert!(known_live_unissued(&c,&p,op.effect_allowed,op.state.as_deref()));assert!(s.permissions.is_empty()&&p.record.phase==Phase::ServerAccepted);
 let mut cold=p.clone();cold.restored=true;assert!(!known_live_unissued(&c,&cold,op.effect_allowed,op.state.as_deref()));let mut ambiguous=p.clone();ambiguous.record.phase=Phase::EffectIntent;assert!(!known_live_unissued(&c,&ambiguous,op.effect_allowed,op.state.as_deref()));
 c.binding.scope.world_token=Some(uuid::Uuid::new_v4().to_string());assert!(!known_live_unissued(&c,&p,op.effect_allowed,op.state.as_deref()));gold_capacity_cleanup(c,dir);
});}
